// TestLoadTermbenchSubset_Canary verifies the three-task canary manifest
// parses cleanly through the same loader the matrix runner uses, and that
// the contract chosen in Step 6 of the harness-matrix plan is preserved:
// exactly the three task IDs fix-git, log-summary-date-ranges, and
// git-leak-recovery, pinned to the same TB-2 commit as the full subset.
// (hello-world was replaced with fix-git; it is not present in TB-2.)
func TestLoadTermbenchSubset_Canary(t *testing.T) {
	path := filepath.Join("..", "..", "scripts", "beadbench", "external", "termbench-subset-canary.json")
	subset, err := loadTermbenchSubset(path)
	if err != nil {
		t.Fatalf("load canary subset: %v", err)
	}

	wantIDs := []string{"fix-git", "log-summary-date-ranges", "git-leak-recovery"}
	if got := len(subset.Tasks); got != len(wantIDs) {
		t.Fatalf("canary must contain exactly %d tasks, got %d", len(wantIDs), got)
	}
	gotIDs := make(map[string]termbenchSubsetEntry, len(subset.Tasks))
	for _, e := range subset.Tasks {
		gotIDs[e.ID] = e
	}
	for _, id := range wantIDs {
		entry, ok := gotIDs[id]
		if !ok {
			t.Errorf("canary missing required task %q", id)
			continue
		}
		if entry.Category == "" || entry.Difficulty == "" || entry.Rationale == "" {
			t.Errorf("task %q must have category, difficulty, and rationale populated", id)
		}
		if entry.Difficulty == "hard" {
			t.Errorf("task %q is hard; canary excludes hard tasks (variance dominates with 3 reps)", id)
		}
	}

	const wantCommit = "53ff2b87d621bdb97b455671f2bd9728b7d86c11"
	if subset.DatasetCommit != wantCommit {
		t.Errorf("canary must pin to TB-2 commit %s, got %q", wantCommit, subset.DatasetCommit)
	}
	if subset.Dataset != "terminal-bench@2.0" {
		t.Errorf("canary dataset = %q, want terminal-bench@2.0", subset.Dataset)
	}
}

func TestLoadTermbenchSubset_LocalWideAllTasksExist(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	path := filepath.Join(repoRoot, "scripts", "beadbench", "external", "termbench-subset-local-wide.json")
	subset, err := loadTermbenchSubset(path)
	if err != nil {
		t.Fatalf("load local-wide subset: %v", err)
	}
	if got, want := len(subset.Tasks), 15; got != want {
		t.Fatalf("local-wide task count = %d, want %d", got, want)
	}
	tasksDir := filepath.Join(repoRoot, "scripts", "benchmark", "external", "terminal-bench-2")
	if _, err := os.Stat(filepath.Join(tasksDir, subset.Tasks[0].ID)); err != nil {
		t.Skipf("terminal-bench-2 tree unavailable in this worktree: %v", err)
	}
	for _, task := range subset.Tasks {
		if _, err := os.Stat(filepath.Join(tasksDir, task.ID)); err != nil {
			t.Fatalf("local-wide task %q must exist under pinned TB-2 tree: %v", task.ID, err)
		}
		if task.Category == "" || task.Difficulty == "" || task.Rationale == "" {
			t.Fatalf("local-wide task %q missing category/difficulty/rationale", task.ID)
		}
	}
}

	fmt.Fprintf(os.Stderr, "%s matrix: --profiles and --harnesses must not be empty\n", benchCommandName())
	return 2
}

subsetData, err := loadTermbenchSubset(subsetPath)
if err != nil {
	fmt.Fprintf(os.Stderr, "%s matrix: load subset %s: %v\n", benchCommandName(), subsetPath, err)
	return 1
}
profiles, err := selectMatrixProfiles(wd, profileIDs)
if err != nil {
	fmt.Fprintf(os.Stderr, "%s matrix: %v\n", benchCommandName(), err)
	return 1
}
if err := os.MkdirAll(outDir, 0o750); err != nil {
	fmt.Fprintf(os.Stderr, "%s matrix: create output dir: %v\n", benchCommandName(), err)
	return 1
}

// Resolve harbor binary if tasks-dir is set (enables graded runs via Docker).
resolvedTasksDir := *tasksDir
if resolvedTasksDir != "" && !filepath.IsAbs(resolvedTasksDir) {
	resolvedTasksDir = filepath.Join(wd, resolvedTasksDir)
}
harborBin := ""
if resolvedTasksDir != "" {
	if bin, err := exec.LookPath("harbor"); err == nil {
		harborBin = bin
	} else {
		fmt.Fprintf(os.Stderr, "%s matrix: --tasks-dir set but harbor not found on PATH\n", benchCommandName())
		return 1
	}
}

// Build the full list of tuples to run.
type tupleSpec struct {
	harness string
	prof    *profile.Profile
	rep     int
	task    termbenchSubsetEntry
}
var tuples []tupleSpec
for _, harness := range harnesses {
	for _, prof := range profiles {
		for rep := 1; rep <= *reps; rep++ {
			for _, task := range subsetData.Tasks {
				tuples = append(tuples, tupleSpec{harness, prof, rep, task})
			}
		}
	}
}

concurrency := *jobs
if concurrency < 1 {
	concurrency = 1
}
consecutiveFailureHalt := !*noConsecutiveFailureHalt

type tupleResult struct {
	report  matrixRunReport
	skipped bool
	err     error
}

var (
	mu              sync.Mutex
	accumulatedCost float64
	firstErr        error
	laneAborted     bool
)

runTuple := func(spec tupleSpec) tupleResult {
	mu.Lock()
	cost := accumulatedCost
	mu.Unlock()

	report, skipped, err := runMatrixTuple(matrixTupleOptions{
		workDir:           wd,
		outDir:            outDir,
		cellsRoot:         cellRootDir,
		harness:           spec.harness,
		profile:           spec.prof,
		rep:               spec.rep,
		task:              spec.task,
		dataset:           subsetData.Dataset,
		datasetVersion:    matrixDatasetVersion(subsetData.Dataset),
		budgetUSD:         *budgetUSD,
		perRunBudgetUSD:   *perRunBudgetUSD,
		accumulatedCost:   cost,
		resume:            *resume,
		forceRerun:        *forceRerun,
		retryBudgetHalted: *retryBudgetHalted,
		retryInvalid:      *retryInvalid,
		parentCtx:         parentCtx,
		tasksDir:          resolvedTasksDir,
		harborBin:         harborBin,
		extraEnv:          extraEnvMap(extraEnv),
	})

	mu.Lock()
	if err != nil && firstErr == nil {
		firstErr = err
	}
	if err == nil && !skipped {
		accumulatedCost += report.CostUSD
	}
	mu.Unlock()
	return tupleResult{report: report, skipped: skipped, err: err}
}

var results []tupleResult
if consecutiveFailureHalt {
	if concurrency > 1 {
		concurrency = 1
	}
	trackers := map[string]*matrixConsecutiveFailureTracker{}
	for _, spec := range tuples {
		result := runTuple(spec)
		results = append(results, result)
		if result.err != nil {
			break
		}
		if result.skipped {
			continue
		}
		laneID := matrixLaneID(spec.harness, spec.prof.ID)
		tracker := trackers[laneID]
		if tracker == nil {
			tracker = newMatrixConsecutiveFailureTracker(matrixConsecutiveFailureLimit)
			trackers[laneID] = tracker
		}
		if abort, details := tracker.Observe(result.report); abort {
			abortReport, err := writeMatrixLaneAbortReport(outDir, cellRootDir, laneID, result.report, details)
			if err != nil {
				firstErr = err
				break
			}
			fmt.Fprintf(os.Stderr, "[matrix] lane=%s ABORTED after %d consecutive identical failures (last task: %s): %s\n",
				laneID, matrixConsecutiveFailureLimit, result.report.TaskID, matrixErrorPreview(result.report.Error))
			results = append(results, tupleResult{report: abortReport})
			laneAborted = true
			break
		}
	}
} else {
	results = make([]tupleResult, len(tuples))
	sem := make(chan struct{}, concurrency)
	var wg sync.WaitGroup
	for i, spec := range tuples {
		wg.Add(1)
		go func(i int, spec tupleSpec) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			results[i] = runTuple(spec)
		}(i, spec)
	}
	wg.Wait()
}

if firstErr != nil {

	if firstErr != nil {
		fmt.Fprintf(os.Stderr, "%s matrix: %v\n", benchCommandName(), firstErr)
		return 1
	}

	var runs []matrixRunReport
	for _, r := range results {
		if r.err != nil {
			continue
		}
		runs = append(runs, r.report)
	}

	sort.Slice(runs, func(i, j int) bool {
		return matrixRunKey(runs[i]) < matrixRunKey(runs[j])
	})
	output := matrixOutput{
		GeneratedAt:     time.Now().UTC(),
		SubsetPath:      subsetPath,
		Profiles:        profileIDs,
		Harnesses:       harnesses,
		Reps:            *reps,
		BudgetUSD:       *budgetUSD,
		PerRunBudgetUSD: *perRunBudgetUSD,
		InvalidRuns:     countMatrixInvalids(runs),
		InvalidByClass:  summarizeMatrixInvalids(runs),
		Runs:            runs,
		Cells:           summarizeMatrixCells(runs),
		Notes: []string{
			fmt.Sprintf("concurrency: --jobs %d", concurrency),
			"adapter_module records the Python adapter path passed by the runner for the harness cell.",
		},
	}
	matrixPath := filepath.Join(outDir, "matrix.json")
	if err := writeJSONAtomic(matrixPath, output); err != nil {
		fmt.Fprintf(os.Stderr, "%s matrix: write matrix.json: %v\n", benchCommandName(), err)
		return 1
	}
	fmt.Printf("matrix results: %s\n", matrixPath)
	if laneAborted {
		return matrixLaneAbortCode
	}
	return 0
}

type matrixTupleOptions struct {
	workDir           string
	outDir            string
	cellsRoot         string
	harness           string
	profile           *profile.Profile
	rep               int
	task              termbenchSubsetEntry
	dataset           string
	datasetVersion    string
	budgetUSD         float64
	perRunBudgetUSD   float64
	accumulatedCost   float64
	resume            bool
	forceRerun        bool
	retryBudgetHalted bool
	retryInvalid      bool
	parentCtx         context.Context // cancelled on parent SIGTERM/SIGINT
	tasksDir          string          // when set, use harbor run for grading
	harborBin         string          // path to harbor binary
	extraEnv          map[string]string
}

type matrixFailureFingerprint struct {
	hash         string
	errorPreview string
	taskIDs      []string
}

type matrixFailureFingerprintEntry struct {
	hash         string
	taskID       string
	errorPreview string
}

type matrixConsecutiveFailureTracker struct {
	limit   int
	last    string
	entries []matrixFailureFingerprintEntry
}

func newMatrixConsecutiveFailureTracker(limit int) *matrixConsecutiveFailureTracker {
	return &matrixConsecutiveFailureTracker{limit: limit}
}

func (t *matrixConsecutiveFailureTracker) Observe(report matrixRunReport) (bool, matrixFailureFingerprint) {
	if t == nil || t.limit <= 0 || !matrixReportCountsForFailureHalt(report) {
		if t != nil {
			t.reset()
		}
		return false, matrixFailureFingerprint{}
	}
	hash := matrixFailureHash(report)
	entry := matrixFailureFingerprintEntry{
		hash:         hash,
		taskID:       report.TaskID,

		taskID:       report.TaskID,
		errorPreview: matrixErrorPreview(report.Error),
	}
	if hash != t.last {
		t.last = hash
		t.entries = []matrixFailureFingerprintEntry{entry}
		return false, matrixFailureFingerprint{}
	}
	t.entries = append(t.entries, entry)
	if len(t.entries) > t.limit {
		t.entries = t.entries[len(t.entries)-t.limit:]
	}
	if len(t.entries) < t.limit {
		return false, matrixFailureFingerprint{}
	}
	taskIDs := make([]string, 0, len(t.entries))
	for _, e := range t.entries {
		taskIDs = append(taskIDs, e.taskID)
	}
	return true, matrixFailureFingerprint{
		hash:         hash,
		errorPreview: entry.errorPreview,
		taskIDs:      taskIDs,
	}
}

func (t *matrixConsecutiveFailureTracker) reset() {
	t.last = ""
	t.entries = nil
}

func matrixReportCountsForFailureHalt(report matrixRunReport) bool {
	if strings.TrimSpace(report.Error) == "" {
		return false
	}
	return report.FinalStatus == "graded_fail" || report.FinalStatus == "harness_crash"
}

func matrixFailureHash(report matrixRunReport) string {
	errorBytes := []byte(report.Error)
	if len(errorBytes) > 256 {
		errorBytes = errorBytes[:256]
	}
	h := sha256.New()
	_, _ = h.Write(errorBytes)
	_, _ = h.Write([]byte{0})
	_, _ = h.Write([]byte(report.FinalStatus))
	return hex.EncodeToString(h.Sum(nil))
}

func matrixErrorPreview(s string) string {
	s = strings.TrimSpace(strings.Join(strings.Fields(s), " "))
	if len(s) <= 160 {
		return s
	}
	return s[:160]
}

func matrixLaneID(harness, profileID string) string {
	return harness + "/" + profileID
}

func matrixLaneAbortDir(outDir, cellsRoot, laneID string) string {
	root := cellsRoot
	if root == "" {
		root = outDir
	}
	return filepath.Join(root, ".lane_aborted", safeMatrixSegment(strings.ReplaceAll(laneID, "/", "__")))
}

func writeMatrixLaneAbortReport(outDir, cellsRoot, laneID string, last matrixRunReport, details matrixFailureFingerprint) (matrixRunReport, error) {
	now := time.Now().UTC()
	abortDir := matrixLaneAbortDir(outDir, cellsRoot, laneID)
	hashPreview := details.hash
	if len(hashPreview) > 16 {
		hashPreview = hashPreview[:16]
	}
	report := matrixRunReport{
		Harness:            last.Harness,
		ProfileID:          last.ProfileID,
		ProfilePath:        last.ProfilePath,
		ProfileSnapshot:    last.ProfileSnapshot,
		FizToolsVersion:    fiztools.Version,
		AdapterModule:      last.AdapterModule,
		HarborAgent:        last.HarborAgent,
		Rep:                last.Rep,
		TaskID:             last.TaskID,
		OutputDir:          abortDir,
		ProcessOutcome:     matrixInvalidLaneAbort,
		GradingOutcome:     "ungraded",
		FinalStatus:        matrixInvalidLaneAbort,
		InvalidClass:       matrixInvalidLaneAbort,
		Error:              fmt.Sprintf("halted after %d consecutive identical failures: %s", matrixConsecutiveFailureLimit, hashPreview),
		FailureFingerprint: details.hash,
		FailureTaskIDs:     details.taskIDs,
		PricingSource:      last.PricingSource,
		SamplingUsed:       last.SamplingUsed,
		ModelServerInfo:    last.ModelServerInfo,
		StartedAt:          now,
		FinishedAt:         now,
	}
	if details.errorPreview != "" {
		report.Error += " (" + details.errorPreview + ")"
	}
	if err := writeJSONAtomic(filepath.Join(abortDir, "aborted.json"), report); err != nil {
		return matrixRunReport{}, fmt.Errorf("write lane abort report: %w", err)
	}
	return report, nil
}

func runMatrixTuple(opts matrixTupleOptions) (matrixRunReport, bool, error) {
	cellDir := matrixTupleDirFor(opts.outDir, opts.cellsRoot, opts.harness, opts.profile, opts.rep, opts.task.ID, opts.dataset)
	reportPath := filepath.Join(cellDir, matrixReportName)
	if !opts.forceRerun {
		if existing, ok, err := loadExistingMatrixReport(reportPath); err != nil {
			return matrixRunReport{}, false, err
		} else if ok && shouldSkipMatrixReport(existing, opts.resume, opts.retryBudgetHalted, opts.retryInvalid) {
			return existing, true, nil
		}
	}

	release, err := acquireMatrixLock(filepath.Join(cellDir, matrixLockName))
	if err != nil {
		return matrixRunReport{}, false, err
	}
	defer release()

	started := time.Now().UTC()
	report := matrixRunReport{
		Dataset:         opts.dataset,
		DatasetVersion:  opts.datasetVersion,
		Harness:         opts.harness,
		ProfileID:       opts.profile.ID,
		ProfilePath:     opts.profile.Path,
		ProfileSnapshot: opts.profile.Versioning.Snapshot,
		FizToolsVersion: fiztools.Version,
		AdapterModule:   matrixAdapterModule(opts.harness),
		HarborAgent:     filepath.ToSlash(filepath.Join("scripts", "benchmark", "harness_adapters", moduleFileName(opts.harness))) + ":Agent",
		Rep:             opts.rep,
		TaskID:          opts.task.ID,
		Category:        opts.task.Category,
		Difficulty:      opts.task.Difficulty,
		OutputDir:       cellDir,
		StartedAt:       started,
		PricingSource:   profilePricingSource(opts.profile),
		SamplingUsed:    samplingUsedFromProfile(opts.profile),
		ModelServerInfo: queryModelServerInfo(opts.profile),
	}

	if opts.budgetUSD > 0 && opts.accumulatedCost >= opts.budgetUSD {
		report.ProcessOutcome = "budget_halted"
		report.GradingOutcome = "ungraded"
		report.FinalStatus = deriveMatrixFinalStatus(report.ProcessOutcome, report.GradingOutcome, report.Reward, false)
		report.FinishedAt = time.Now().UTC()
		if err := writeJSONAtomic(reportPath, report); err != nil {
			return matrixRunReport{}, false, err
		}
		return report, false, nil
	}

	workDir := filepath.Join(cellDir, "work")
	if err := os.MkdirAll(workDir, 0o750); err != nil {
		return matrixRunReport{}, false, fmt.Errorf("create tuple workdir: %w", err)
	}

	if opts.harborBin != "" {
		taskPath, err := resolveMatrixTaskPath(opts.tasksDir, opts.task.ID)
		if err != nil {
			report.ProcessOutcome = "install_fail_permanent"
			report.GradingOutcome = "ungraded"
			report.Error = err.Error()
		} else {
			// Remove any stale Harbor job dir from a prior run before we
			// invoke harbor again. Harbor (re)creates fiz-<task>-rep<N>/
			// inside --jobs-dir; if a stale subdir exists from an earlier
			// run with a different --tasks-dir, Harbor's config.json there
			// references paths that may no longer exist (or that point at
			// since-deleted timestamp dirs), and the trial fails with
			// confusing errors. Wiping ensures a clean Harbor invocation
			// every retry.
			jobName := fmt.Sprintf("%s-%s-rep%d", opts.harness, opts.task.ID, opts.rep)
			staleJobDir := filepath.Join(cellDir, jobName)
			if _, err := os.Stat(staleJobDir); err == nil {
				_ = os.RemoveAll(staleJobDir)
			}
			harborResult, err := runMatrixHarbor(harborRunOpts{
				harborBin: opts.harborBin,
				taskPath:  taskPath,
				harness:   opts.harness,
				profile:   opts.profile,
				jobsDir:   cellDir,
				jobName:   jobName,
				repoRoot:  opts.workDir,
				extraEnv:  opts.extraEnv,
				parentCtx: opts.parentCtx,
			})
			if err != nil {
				report.ProcessOutcome = "harness_crash"
				report.GradingOutcome = "ungraded"
				report.Error = err.Error()
			} else {
				report.ExitCode = harborResult.exitCode
				report.Error = harborResult.errText
				seconds := harborResult.wallSeconds
				report.WallSeconds = &seconds
				if harborResult.inputTokens != nil {
					report.InputTokens = harborResult.inputTokens
				}
				if harborResult.outputTokens != nil {
					report.OutputTokens = harborResult.outputTokens
				}
				if harborResult.turns != nil {
					report.Turns = harborResult.turns
				}
				report.CostUSD = harborResult.costUSD
				if harborResult.reward != nil {
					report.Reward = harborResult.reward
					report.GradingOutcome = "graded"
					report.ProcessOutcome = "completed"
				} else if harborResult.exitCode != 0 {
					report.ProcessOutcome = "harness_crash"
					report.GradingOutcome = "ungraded"
				} else {
					report.ProcessOutcome = "completed"
					report.GradingOutcome = "ungraded"
				}
			}
			// Read session-jsonl signals (terminated_mid_work + had_llm_request
			// + reasoning_tokens) from the trial's session jsonl. The harbor
			// agent (FizeauAgent) writes to <cellDir>/<jobName>/<trial-hash>/
			// agent/sessions/svc-*.jsonl; glob for the newest since the
			// trial-hash isn't known up front. Mirrors backfill-terminated-
			// mid-work.py.
			tmw, hadReq, reasoning, reasoningApprox := readSessionSignalsFromCell(filepath.Join(cellDir, jobName))
			if tmw != nil {
				report.TerminatedMidWork = tmw
			}
			if reasoning != nil {
				report.ReasoningTokens = reasoning
				report.ReasoningTokensApprox = reasoningApprox
			}

// Package profile is the canonical reader for v7 benchmark profile YAML files
// under scripts/benchmark/profiles/. The schema is frozen by SD-010 §3
// (Harness × Model Matrix Benchmark); additive fields require a spec amendment.
package profile

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// ProviderType enumerates the provider client paths supported by the
// matrix runner. SD-010 §3 forbids silent override; the adapter selects its
// client path by exact match on this field.
type ProviderType string

const (
	ProviderAnthropic    ProviderType = "anthropic"
	ProviderOpenAI       ProviderType = "openai"
	ProviderOpenAICompat ProviderType = "openai-compat"
	ProviderOpenRouter   ProviderType = "openrouter"
	ProviderOMLX         ProviderType = "omlx"
	ProviderLMStudio     ProviderType = "lmstudio"
	ProviderOllama       ProviderType = "ollama"
	ProviderGoogle       ProviderType = "google"
	ProviderRapidMLX     ProviderType = "rapid-mlx"
	ProviderVLLM         ProviderType = "vllm"
	ProviderLlamaServer  ProviderType = "llama-server"
	ProviderDS4          ProviderType = "ds4"
)

func (p ProviderType) valid() bool {
	switch p {
	case ProviderAnthropic, ProviderOpenAI, ProviderOpenAICompat, ProviderOpenRouter,
		ProviderOMLX, ProviderLMStudio, ProviderOllama, ProviderGoogle, ProviderRapidMLX, ProviderVLLM, ProviderLlamaServer, ProviderDS4:
		return true
	}
	return false
}

// Provider describes how the harness adapter should reach the model API.
type Provider struct {
	Type      ProviderType `yaml:"type"`
	Model     string       `yaml:"model"`
	BaseURL   string       `yaml:"base_url"`
	APIKeyEnv string       `yaml:"api_key_env"`
}

// Pricing is the single source of truth for cost reconciliation. Units are
// USD per million tokens.
type Pricing struct {
	InputUSDPerMTok       float64 `yaml:"input_usd_per_mtok"`
	OutputUSDPerMTok      float64 `yaml:"output_usd_per_mtok"`
	CachedInputUSDPerMTok float64 `yaml:"cached_input_usd_per_mtok"`
}

// Limits captures provider-side ceilings. rate_limit_* are informational in
// v1 (D6 forbids concurrency > 1) and reserved for the follow-up scheduler.
type Limits struct {
	MaxOutputTokens int `yaml:"max_output_tokens"`
	ContextTokens   int `yaml:"context_tokens"`
	RateLimitRPM    int `yaml:"rate_limit_rpm"`
	RateLimitTPM    int `yaml:"rate_limit_tpm"`
}

// Sampling is opaque to the runner; passed verbatim to the adapter's
// apply_profile step. Reasoning is a free-form string ("low" | "medium" |
// "high" | "" depending on the family). Pointer fields are omitted when
// nil so server defaults apply.
type Sampling struct {
	Temperature float64  `yaml:"temperature"`
	Reasoning   string   `yaml:"reasoning,omitempty"`
	TopP        *float64 `yaml:"top_p,omitempty"`
	TopK        *int     `yaml:"top_k,omitempty"`
	MinP        *float64 `yaml:"min_p,omitempty"`
}

// ModelServerInfo is populated at run time by querying the local model server
// (e.g. lmstudio /api/v0/models/<id>). Fields are empty/zero when the server
// does not expose them.
type ModelServerInfo struct {
	Quantization        string `json:"quantization,omitempty"`
	LoadedContextLength int    `json:"loaded_context_length,omitempty"`
	MaxContextLength    int    `json:"max_context_length,omitempty"`
	Source              string `json:"source,omitempty"` // URL queried
}

// Versioning records when the profile was authored and which provider
// snapshot the adapter resolved at apply_profile time.
type Versioning struct {
	ResolvedAt string `yaml:"resolved_at"`
	Snapshot   string `yaml:"snapshot"`
}

// Metadata captures the orthogonal benchmark dimensions a profile occupies in
// the multi-dimensional cells tensor: server, runtime, model family, quant,
// etc. Stamped on every report.json so cells can be projected/grouped by any
// of these axes at index time without re-loading profiles.
//
// The named fields are conveniences for the dimensions we use today; arbitrary
// future dimensions (e.g. experiment_id, prompt_variant, system_prompt_id,
// sampling_preset_label) can be declared in the profile YAML without any
// code change — they are absorbed into Extra and preserved verbatim by the
// catalog snapshot at <canonical>/profiles/. Reporting tools join on
// profile_id and read whatever keys exist.
type Metadata struct {
	Server          string `yaml:"server,omitempty"`
	ModelFamily     string `yaml:"model_family,omitempty"`
	ModelID         string `yaml:"model_id,omitempty"`
	QuantLabel      string `yaml:"quant_label,omitempty"`
	ProviderSurface string `yaml:"provider_surface,omitempty"`
	Runtime         string `yaml:"runtime,omitempty"`
	HardwareLabel   string `yaml:"hardware_label,omitempty"`
	Endpoint        string `yaml:"endpoint,omitempty"`
	// Extra absorbs any metadata keys not in the typed fields above. Use it
	// for ad-hoc experiment dimensions; promote a key to a typed field once
	// it stabilizes. yaml v3 ",inline" merges these into the same map at the
	// metadata block's level rather than a nested map.
	Extra map[string]string `yaml:",inline"`
}

// Profile is the in-memory shape of a frozen v1 profile YAML.
type Profile struct {
	ID         string     `yaml:"id"`
	Metadata   Metadata   `yaml:"metadata,omitempty"`
	Provider   Provider   `yaml:"provider"`
	Pricing    Pricing    `yaml:"pricing"`
	Limits     Limits     `yaml:"limits"`
	Sampling   Sampling   `yaml:"sampling"`
	Versioning Versioning `yaml:"versioning"`

	// AgentTimeoutMultiplier scales harbor's per-task agent timeout to
	// account for slow inference engines. Without this, low-throughput
	// local lanes hit the harbor default mid-tool-call (see the
	// `terminated_mid_work` field on matrix reports). Computed as the p95
	// of per-task wall_local/wall_OR ratios on jointly-passed tasks. Maps
	// directly to harbor's --agent-timeout-multiplier flag. 0 = use
	// harbor default (effectively 1.0). The HARBOR_AGENT_TIMEOUT_MULTIPLIER
	// env var overrides this per-invocation.
	AgentTimeoutMultiplier float64 `yaml:"agent_timeout_multiplier,omitempty"`

	// Path is the filesystem path the profile was loaded from. Not part of
	// the YAML; populated by Load / LoadDir for diagnostics and `profiles
	// list` output.
	Path string `yaml:"-"`
}

// Load reads and validates a single profile YAML file at path.
func Load(path string) (*Profile, error) {
	raw, err := os.ReadFile(path) // #nosec G304 -- path is an operator-supplied profile location, scoped by Validate()
	if err != nil {
		return nil, fmt.Errorf("read profile %s: %w", path, err)
	}
	var p Profile
	dec := yaml.NewDecoder(strings.NewReader(string(raw)))
	dec.KnownFields(true)
	if err := dec.Decode(&p); err != nil {
		return nil, fmt.Errorf("parse profile %s: %w", path, err)
	}
	p.Path = path
	if err := p.Validate(); err != nil {
		return nil, fmt.Errorf("validate profile %s: %w", path, err)
	}
	return &p, nil
}

// LoadDir loads every *.yaml / *.yml file under dir, sorted by id. It is the
// entry point used by `fiz-bench profiles list`.
func LoadDir(dir string) ([]*Profile, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("read profiles dir %s: %w", dir, err)
	}
	var profiles []*Profile
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		ext := strings.ToLower(filepath.Ext(e.Name()))
		if ext != ".yaml" && ext != ".yml" {
			continue
		}
		p, err := Load(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}
		profiles = append(profiles, p)
	}
	sort.Slice(profiles, func(i, j int) bool { return profiles[i].ID < profiles[j].ID })
	return profiles, nil
}

// Validate checks that every required v1 field is present. The schema is
// frozen by SD-010 §3; missing fields are a hard error rather than a warning.
func (p *Profile) Validate() error {
	if strings.TrimSpace(p.ID) == "" {
		return fmt.Errorf("id is required")
	}
	if !p.Provider.Type.valid() {
		return fmt.Errorf("provider.type %q is not one of anthropic|openai|openrouter|omlx|lmstudio|ollama|google|rapid-mlx|vllm|llama-server|ds4", p.Provider.Type)
	}
	if strings.TrimSpace(p.Provider.Model) == "" {
		return fmt.Errorf("provider.model is required")
	}
	if strings.TrimSpace(p.Provider.BaseURL) == "" {
		return fmt.Errorf("provider.base_url is required")
	}
	if strings.TrimSpace(p.Provider.APIKeyEnv) == "" {
		return fmt.Errorf("provider.api_key_env is required")
	}
	if p.Pricing.InputUSDPerMTok < 0 || p.Pricing.OutputUSDPerMTok < 0 || p.Pricing.CachedInputUSDPerMTok < 0 {
		return fmt.Errorf("pricing.* must be non-negative")
	}
	if p.Limits.MaxOutputTokens <= 0 {
		return fmt.Errorf("limits.max_output_tokens must be > 0")
	}
	if p.Limits.ContextTokens <= 0 {
		return fmt.Errorf("limits.context_tokens must be > 0")
	}
	if strings.TrimSpace(p.Versioning.ResolvedAt) == "" {
		return fmt.Errorf("versioning.resolved_at is required")
	}
	return nil
}

