	for _, id := range []string{"fiz-harness-codex-gpt-5-4-mini", "fiz-harness-pi-gpt-5-4-mini", "fiz-harness-opencode-gpt-5-4-mini", "fiz-openrouter-gpt-5-4-mini"} {
